package com.dongqh.luckyhub.fulfillment;
import com.dongqh.luckyhub.auth.model.JwtPayload;import com.dongqh.luckyhub.auth.security.*;import com.dongqh.luckyhub.rbac.service.UserPermissionService;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;import org.springframework.test.context.bean.override.mockito.MockitoBean;import org.springframework.test.web.servlet.MockMvc;import java.util.Set;import static org.mockito.Mockito.when;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;
@SpringBootTest @AutoConfigureMockMvc class FulfillmentSecurityChainIntegrationTests {@Autowired MockMvc mvc;@MockitoBean JwtService jwt;@MockitoBean SessionService sessions;@MockitoBean UserPermissionService permissions;@BeforeEach void caller(){when(jwt.parse("token")).thenReturn(new JwtPayload(7L,"limited","s"));when(sessions.isValid("s",7L)).thenReturn(true);when(permissions.findPermissionCodes(7L)).thenReturn(Set.of());}@Test void protectsBothAdminApiGroups() throws Exception {check(get("/api/admin/fulfillment/tasks"));check(post("/api/admin/fulfillment/tasks/X/retry"));check(post("/api/admin/simulators/failure-rules"));}private void check(org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder r)throws Exception{mvc.perform(r).andExpect(status().isUnauthorized());mvc.perform(r.header("Authorization","Bearer token")).andExpect(status().isForbidden());}}
